"use client"

import { useEffect, useState } from "react"
import Link from "next/link"
import { m } from "framer-motion"
import { AlertTriangle, Copy, Check, RefreshCw, Home, Mail, ChevronDown, ChevronUp, Bug, Terminal, ShieldAlert } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Header } from "@/components/layout/header"
import { LazyMotionProvider } from "@/components/providers/lazy-motion-provider"

interface ErrorProps {
  error: Error & { digest?: string }
  reset: () => void
}

export default function ErrorPage({ error, reset }: ErrorProps) {
  const [copied, setCopied] = useState(false)
  const [showStack, setShowStack] = useState(false)
  const [clientInfo, setClientInfo] = useState<{
    url: string
    timestamp: string
    userAgent: string
    screenSize: string
  }>({
    url: "",
    timestamp: "",
    userAgent: "",
    screenSize: "",
  })

  useEffect(() => {
    // Collect client-side diagnostic data for instant reporting
    if (typeof window !== "undefined") {
      setClientInfo({
        url: window.location.href,
        timestamp: new Date().toLocaleString(),
        userAgent: navigator.userAgent,
        screenSize: `${window.innerWidth}x${window.innerHeight}`,
      })
    }
  }, [])

  // Construct structured diagnostic report
  const generateReport = () => {
    return [
      `### 🐛 RHHS Classroom Champion - Bug Report`,
      ``,
      `**Error Message**: ${error.message || "Unknown error"}`,
      `**Error Name**: ${error.name || "Error"}`,
      `**Digest ID**: ${error.digest || "None"}`,
      `**Timestamp**: ${clientInfo.timestamp || new Date().toISOString()}`,
      `**Page URL**: ${clientInfo.url || "N/A"}`,
      `**Screen Size**: ${clientInfo.screenSize || "N/A"}`,
      `**User Agent**: ${clientInfo.userAgent || "N/A"}`,
      ``,
      `#### Stack Trace:`,
      "```",
      error.stack || "No stack trace available",
      "```",
    ].join("\n")
  }

  const handleCopyReport = async () => {
    try {
      await navigator.clipboard.writeText(generateReport())
      setCopied(true)
      setTimeout(() => setCopied(false), 3000)
    } catch (err) {
      console.error("Failed to copy report to clipboard:", err)
    }
  }

  const getMailtoLink = () => {
    const subject = encodeURIComponent(`[Bug Report] RHHS Classroom Champion - ${error.name || "App Error"}`)
    const body = encodeURIComponent(
      `Hello RHHS Dev Team,\n\nI encountered the following issue while using the application:\n\n${generateReport()}\n\nAdditional Details:\n[Please describe what you clicked or were trying to do here]`
    )
    return `mailto:baraa.elmallah@rhhs.edu.lb?subject=${subject}&body=${body}`
  }

  return (
    <LazyMotionProvider>
      <div className="min-h-screen bg-linear-to-b from-background via-background to-destructive/5 flex flex-col relative overflow-hidden">
        <Header />

        <main id="main-content" className="flex-1 container mx-auto px-4 py-12 flex flex-col items-center justify-center relative z-10">
          <m.div
            className="w-full max-w-2xl bg-card border border-destructive/30 rounded-2xl p-6 sm:p-8 shadow-xl backdrop-blur-sm"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
          >
            {/* Header / Error Icon */}
            <div className="flex items-center gap-4 mb-6">
              <div className="h-14 w-14 rounded-2xl bg-destructive/10 border border-destructive/20 flex items-center justify-center text-destructive shrink-0">
                <ShieldAlert className="h-8 w-8" />
              </div>
              <div>
                <span className="text-xs uppercase font-bold tracking-wider text-destructive flex items-center gap-1.5">
                  <AlertTriangle className="h-3.5 w-3.5" /> Runtime Exception Caught
                </span>
                <h1 className="text-2xl sm:text-3xl font-bold text-foreground">
                  Something Wilted Unexpectedly
                </h1>
              </div>
            </div>

            <p className="text-muted-foreground text-sm sm:text-base leading-relaxed mb-6">
              The application encountered an unexpected issue while processing your request. You don't need to open the browser console — all developer diagnostic details are captured below.
            </p>

            {/* Quick Action Buttons */}
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-2.5 mb-6">
              <Button
                onClick={() => reset()}
                className="w-full rounded-xl bg-primary hover:bg-primary/90 text-primary-foreground font-semibold shadow-sm"
              >
                <RefreshCw className="mr-2 h-4 w-4" /> Try Again
              </Button>

              <Button
                onClick={handleCopyReport}
                variant="outline"
                className="w-full rounded-xl border-border hover:bg-muted font-medium transition-colors"
              >
                {copied ? (
                  <>
                    <Check className="mr-2 h-4 w-4 text-emerald-500" /> Copied Report!
                  </>
                ) : (
                  <>
                    <Copy className="mr-2 h-4 w-4" /> Copy Error Info
                  </>
                )}
              </Button>

              <Button
                asChild
                variant="outline"
                className="w-full rounded-xl border-border hover:bg-muted font-medium"
              >
                <a href={getMailtoLink()} target="_blank" rel="noopener noreferrer">
                  <Mail className="mr-2 h-4 w-4 text-blue-500" /> Report Issue
                </a>
              </Button>
            </div>

            {/* Structured Error Details Card */}
            <div className="bg-muted/50 border border-border/80 rounded-xl p-4 mb-4 space-y-3 font-mono text-xs">
              <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-1 pb-2 border-b border-border/50">
                <span className="text-muted-foreground font-semibold">Error Message:</span>
                <span className="text-destructive font-bold break-all text-left sm:text-right">
                  {error.message || "An unknown exception occurred."}
                </span>
              </div>

              {error.digest && (
                <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-1 pb-2 border-b border-border/50">
                  <span className="text-muted-foreground font-semibold">Digest Reference:</span>
                  <span className="text-foreground bg-background px-2 py-0.5 rounded border border-border/50">
                    {error.digest}
                  </span>
                </div>
              )}

              <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-1 pb-2 border-b border-border/50">
                <span className="text-muted-foreground font-semibold">Request Location:</span>
                <span className="text-foreground truncate max-w-xs">{clientInfo.url || "/"}</span>
              </div>

              <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-1">
                <span className="text-muted-foreground font-semibold">Timestamp:</span>
                <span className="text-muted-foreground">{clientInfo.timestamp || "Just now"}</span>
              </div>
            </div>

            {/* Collapsible Stack Trace */}
            {error.stack && (
              <div className="mb-6">
                <button
                  type="button"
                  onClick={() => setShowStack(!showStack)}
                  className="flex items-center justify-between w-full text-xs font-semibold text-muted-foreground hover:text-foreground py-2 px-1 transition-colors"
                >
                  <span className="flex items-center gap-1.5">
                    <Terminal className="h-3.5 w-3.5" /> Technical Stack Trace
                  </span>
                  {showStack ? <ChevronUp className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />}
                </button>

                {showStack && (
                  <m.div
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    className="mt-2 p-3 bg-zinc-950 text-zinc-300 rounded-xl overflow-x-auto text-[11px] font-mono leading-relaxed border border-border/40 max-h-56 scrollbar-thin"
                  >
                    <pre className="whitespace-pre-wrap break-all">{error.stack}</pre>
                  </m.div>
                )}
              </div>
            )}

            {/* Bottom Return Action */}
            <div className="pt-4 border-t border-border/60 flex items-center justify-between">
              <span className="text-xs text-muted-foreground flex items-center gap-1.5">
                <Bug className="h-3.5 w-3.5" /> Report goes to Technical Team
              </span>
              <Button asChild variant="ghost" size="sm" className="rounded-lg">
                <Link href="/">
                  <Home className="mr-1.5 h-4 w-4" /> Back to Home
                </Link>
              </Button>
            </div>
          </m.div>
        </main>
      </div>
    </LazyMotionProvider>
  )
}

"use client"

import { TodayLabel } from "@/components/common/today-label"
import { EcoLoader } from "@/components/common/eco-loader"
import { Suspense, useState, useEffect, useMemo, useTransition, useCallback } from "react"
import { useRouter, useSearchParams } from "next/navigation"
import { ProtectedRoute } from "@/components/providers/protected-route"
import { DashboardHeader } from "@/components/layout/dashboard-header"
import { ClassroomSelector } from "@/components/features/evaluations/classroom-selector"
import { EvaluationForm } from "@/components/features/evaluations/evaluation-form"
import { EvaluationSuccess } from "@/components/features/evaluations/evaluation-success"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog"
import { Input } from "@/components/ui/input"
import { getClassrooms } from "@/lib/supabase-data"
import type { Classroom, User } from "@/lib/types"
import { getEvaluationsStatus } from "@/app/actions/evaluation-settings-actions"
import {
  getDateClassroomEvaluationOverview,
  type DateEvaluationOverview,
  type DateClassroomStatus,
  type MissedDayRecord
} from "@/app/actions/calendar-actions"
import {
  AlertCircle,
  Calendar,
  Clock,
  Sparkles,
  ArrowLeft,
  ChevronRight,
  CheckCircle2,
  CalendarDays,
  Info,
  RotateCcw
} from "lucide-react"
import { format, parseISO, isToday, isPast, isFuture, isWeekend } from "date-fns"
import { cn } from "@/lib/utils"

type ViewState = "select" | "evaluate" | "success" | "closed"

interface SupervisorEvaluateContentProps {
  currentUser?: User
}

function useSupervisorEvaluateContentController({ currentUser }: SupervisorEvaluateContentProps) {
  const router = useRouter()
  const searchParams = useSearchParams()
  const todayStr = format(new Date(), "yyyy-MM-dd")

  // URL state
  const dateParam = searchParams.get("date") || todayStr
  const classroomIdParam = searchParams.get("classroom")

  const [currentDate, setCurrentDate] = useState<string>(dateParam)
  const [viewState, setViewState] = useState<ViewState>("select")
  const [selectedClassroom, setSelectedClassroom] = useState<Classroom | null>(null)
  const [classrooms, setClassrooms] = useState<Classroom[]>([])
  const [loading, setLoading] = useState(true)

  // Date Evaluation Overview State
  const [dateOverview, setDateOverview] = useState<DateEvaluationOverview | null>(null)
  const [loadingOverview, setLoadingOverview] = useState(false)
  const [isDatePickerOpen, setIsDatePickerOpen] = useState(false)
  const [customDateInput, setCustomDateInput] = useState(currentDate)

  // Keep internal currentDate in sync with URL date param if it changes
  useEffect(() => {
    if (dateParam && dateParam !== currentDate) {
      setCurrentDate(dateParam)
      setCustomDateInput(dateParam)
    }
  }, [dateParam, currentDate])

  // 1. Initial system check & fetch classrooms
  useEffect(() => {
    let cancelled = false
    const checkStatusAndFetchClassrooms = async () => {
      try {
        const statusResult = await getEvaluationsStatus()
        if (statusResult.success && statusResult.enabled === false) {
          if (!cancelled) {
            setViewState("closed")
            setLoading(false)
          }
          return
        }

        const data = await getClassrooms()
        if (!cancelled) {
          setClassrooms(data)
        }
      } catch (error) {
        console.error("Error fetching classrooms:", error)
      } finally {
        if (!cancelled) setLoading(false)
      }
    }

    void checkStatusAndFetchClassrooms()
    return () => {
      cancelled = true
    }
  }, [])

  // 2. Load evaluation overview for currentDate
  const loadDateOverview = useCallback(
    async (targetDateStr: string, signal?: AbortSignal) => {
      if (!currentUser) return
      setLoadingOverview(true)
      try {
        const res = await getDateClassroomEvaluationOverview(targetDateStr, currentUser.id)
        if (signal?.aborted) return
        if (res.success && res.data) {
          setDateOverview(res.data)
        }
      } catch (err) {
        if (signal?.aborted) return
        console.error("Error loading date overview:", err)
      } finally {
        if (!signal?.aborted) setLoadingOverview(false)
      }
    },
    [currentUser]
  )

  useEffect(() => {
    const controller = new AbortController()
    void loadDateOverview(currentDate, controller.signal)
    return () => controller.abort()
  }, [loadDateOverview, currentDate])

  // 3. Synchronize selected classroom from URL parameters (without viewState dependency trap)
  useEffect(() => {
    if (viewState === "closed" || classrooms.length === 0) return

    const classroomId = searchParams.get("classroom")
    if (classroomId) {
      const classroom = classrooms.find((c) => c.id === classroomId)
      if (classroom) {
        setSelectedClassroom(classroom)
        setViewState("evaluate")
        return
      }
    }

    // If no classroom param in URL and not in success view, show selector
    if (!classroomId && viewState !== "success") {
      setSelectedClassroom(null)
      setViewState("select")
    }
  }, [searchParams, classrooms, viewState])

  // Helpers for date status map
  const dateStatusMap = useMemo<Record<string, DateClassroomStatus>>(() => {
    if (!dateOverview) return {}
    const map: Record<string, DateClassroomStatus> = {}
    dateOverview.classrooms.forEach((c) => {
      map[c.id] = c
    })
    return map
  }, [dateOverview])

  const parsedCurrentDate = parseISO(currentDate)
  const isDateToday = isToday(parsedCurrentDate)
  const isDateInPast = isPast(parsedCurrentDate) && !isDateToday
  const missedDaysList: MissedDayRecord[] = dateOverview?.missedDays || []

  // Handlers
  const handleSwitchDate = (newDate: string) => {
    if (newDate === currentDate) {
      setIsDatePickerOpen(false)
      return
    }
    setCurrentDate(newDate)
    setCustomDateInput(newDate)
    setIsDatePickerOpen(false)
    // Clear classroom selection on date switch and update URL
    setSelectedClassroom(null)
    setViewState("select")
    router.replace(`/supervisor/evaluate?date=${newDate}`)
  }

  const handleClassroomSelect = (classroom: Classroom) => {
    setSelectedClassroom(classroom)
    setViewState("evaluate")
    router.replace(`/supervisor/evaluate?classroom=${classroom.id}&date=${currentDate}`)
  }

  const handleEvaluationComplete = () => {
    setViewState("success")
    // Refresh date overview to update scores
    void loadDateOverview(currentDate)
  }

  const handleNewEvaluation = () => {
    setSelectedClassroom(null)
    setViewState("select")
    router.replace(`/supervisor/evaluate?date=${currentDate}`)
  }

  const handleCancel = () => {
    setSelectedClassroom(null)
    setViewState("select")
    router.replace(`/supervisor/evaluate?date=${currentDate}`)
  }

  const handleBackToDashboard = () => {
    router.push("/supervisor")
  }
  return {
    currentDate,
    customDateInput,
    dateOverview,
    dateStatusMap,
    handleBackToDashboard,
    handleCancel,
    handleClassroomSelect,
    handleEvaluationComplete,
    handleNewEvaluation,
    handleSwitchDate,
    isDateInPast,
    isDatePickerOpen,
    isDateToday,
    loading,
    loadingOverview,
    missedDaysList,
    parsedCurrentDate,
    selectedClassroom,
    setCustomDateInput,
    setIsDatePickerOpen,
    todayStr,
    viewState
  }
}

function SupervisorEvaluateContent({ currentUser }: SupervisorEvaluateContentProps) {
  const {
    currentDate,
    customDateInput,
    dateOverview,
    dateStatusMap,
    handleBackToDashboard,
    handleCancel,
    handleClassroomSelect,
    handleEvaluationComplete,
    handleNewEvaluation,
    handleSwitchDate,
    isDateInPast,
    isDatePickerOpen,
    isDateToday,
    loading,
    loadingOverview,
    missedDaysList,
    parsedCurrentDate,
    selectedClassroom,
    setCustomDateInput,
    setIsDatePickerOpen,
    todayStr,
    viewState
  } = useSupervisorEvaluateContentController({ currentUser })

  if (!currentUser) return null

  return (
    <div className="min-h-screen bg-background">
      <DashboardHeader user={currentUser} />

      <main className="container mx-auto px-3 sm:px-4 py-5 sm:py-8 max-w-5xl space-y-4">
        {/* Top Header & Navigation Breadcrumb */}
        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
          <div>
            <div className="flex items-center gap-2 mb-1">
              <Button
                variant="outline"
                size="sm"
                onClick={handleBackToDashboard}
                className="text-xs h-8 rounded-xl px-2.5 cursor-pointer"
              >
                <ArrowLeft className="h-3.5 w-3.5 mr-1" /> Dashboard
              </Button>
              <span className="text-xs text-muted-foreground">/</span>
              <span className="text-xs font-semibold text-foreground">Classroom Evaluation</span>
            </div>
            <h1 className="text-2xl sm:text-3xl font-black tracking-tight text-foreground">Classroom Evaluation</h1>
            <p className="text-xs sm:text-sm text-muted-foreground">
              Record daily eco-friendly practices and points for RHHS classrooms
            </p>
          </div>

          {/* Today Quick Action if currently viewing a backfill date */}
          {!isDateToday && (
            <Button
              variant="outline"
              size="sm"
              onClick={() => handleSwitchDate(todayStr)}
              className="rounded-xl text-xs h-9 bg-primary/5 hover:bg-primary/10 text-primary border-primary/30 cursor-pointer"
            >
              <RotateCcw className="h-3.5 w-3.5 mr-1.5" /> Return to Today&apos;s Inspection
            </Button>
          )}
        </div>

        {/* ========================================================================= */}
        {/* INTERACTIVE DATE & BACKFILL CONTROL BAR */}
        {/* ========================================================================= */}
        {viewState !== "closed" && (
          <InspectionDateNavigation
            currentDate={currentDate}
            dateOverview={dateOverview}
            handleSwitchDate={handleSwitchDate}
            isDateToday={isDateToday}
            missedDaysList={missedDaysList}
            parsedCurrentDate={parsedCurrentDate}
            setIsDatePickerOpen={setIsDatePickerOpen}
            todayStr={todayStr}
          />
        )}

        {/* Main Content Areas */}
        {loading ? (
          <EcoLoader title="Preparing the evaluation center" />
        ) : (
          <InspectionWorkspace
            currentDate={currentDate}
            currentUser={currentUser}
            dateOverview={dateOverview}
            dateStatusMap={dateStatusMap}
            handleBackToDashboard={handleBackToDashboard}
            handleCancel={handleCancel}
            handleClassroomSelect={handleClassroomSelect}
            handleEvaluationComplete={handleEvaluationComplete}
            handleNewEvaluation={handleNewEvaluation}
            isDateInPast={isDateInPast}
            loadingOverview={loadingOverview}
            parsedCurrentDate={parsedCurrentDate}
            selectedClassroom={selectedClassroom}
            setIsDatePickerOpen={setIsDatePickerOpen}
            viewState={viewState}
          />
        )}
      </main>

      {/* ========================================================================= */}
      {/* DATE PICKER & BACKFILL SELECTOR DIALOG */}
      {/* ========================================================================= */}
      <InspectionDatePicker
        currentDate={currentDate}
        customDateInput={customDateInput}
        dateOverview={dateOverview}
        handleSwitchDate={handleSwitchDate}
        isDatePickerOpen={isDatePickerOpen}
        missedDaysList={missedDaysList}
        setCustomDateInput={setCustomDateInput}
        setIsDatePickerOpen={setIsDatePickerOpen}
        todayStr={todayStr}
      />
    </div>
  )
}

function SupervisorEvaluatePageContent() {
  return (
    <ProtectedRoute allowedRoles={["supervisor"]}>
      <SupervisorEvaluateContent />
    </ProtectedRoute>
  )
}

export default function SupervisorEvaluatePage() {
  return (
    <Suspense fallback={<div className="min-h-screen bg-background" />}>
      <SupervisorEvaluatePageContent />
    </Suspense>
  )
}

function InspectionDateNavigation({
  currentDate,
  dateOverview,
  handleSwitchDate,
  isDateToday,
  missedDaysList,
  parsedCurrentDate,
  setIsDatePickerOpen,
  todayStr
}: Pick<
  ReturnType<typeof useSupervisorEvaluateContentController>,
  | "currentDate"
  | "dateOverview"
  | "handleSwitchDate"
  | "isDateToday"
  | "missedDaysList"
  | "parsedCurrentDate"
  | "setIsDatePickerOpen"
  | "todayStr"
>) {
  return (
    <Card className="rounded-2xl border-border bg-card shadow-xs overflow-hidden">
      <div className="p-4 sm:p-5 space-y-3.5">
        {/* Row 1: Active Date Banner & Switcher */}
        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
          <div className="flex items-center gap-3">
            <div
              className={cn(
                "h-11 w-11 rounded-2xl flex items-center justify-center shrink-0 shadow-2xs",
                isDateToday ? "bg-primary/15 text-primary" : "bg-amber-500/15 text-amber-600 dark:text-amber-400"
              )}
            >
              {isDateToday ? <Sparkles className="h-5 w-5" /> : <Calendar className="h-5 w-5" />}
            </div>

            <div>
              <div className="flex items-center gap-2">
                <span className="text-base sm:text-lg font-bold text-foreground">
                  {format(parsedCurrentDate, "EEEE, MMMM d, yyyy")}
                </span>
                {isDateToday ? (
                  <Badge
                    variant="outline"
                    className="bg-primary/10 text-primary border-primary/20 text-[10px] px-2 py-0.5 rounded-md"
                  >
                    Today&apos;s Live
                  </Badge>
                ) : (
                  <Badge
                    variant="outline"
                    className="bg-amber-500/15 text-amber-700 dark:text-amber-300 border-amber-500/30 text-[10px] px-2 py-0.5 rounded-md"
                  >
                    Backfilling Past Day
                  </Badge>
                )}
              </div>
              <p className="text-xs text-muted-foreground mt-0.5">
                {isDateToday
                  ? "Evaluations recorded now will count towards today's daily points."
                  : "Backfilling points for this past date. Completed evaluations will be locked."}
              </p>
            </div>
          </div>

          {/* Date Switcher Trigger Button */}
          <div className="flex items-center gap-2 self-end sm:self-auto shrink-0">
            {dateOverview && (
              <div className="text-right hidden md:block mr-2">
                <div className="text-xs font-bold text-foreground">
                  {dateOverview.completedCount} / {dateOverview.totalAssigned} Rooms Done
                </div>
                <div className="text-[10px] text-muted-foreground">
                  {dateOverview.pendingCount} pending for this date
                </div>
              </div>
            )}

            <Button
              variant="outline"
              size="sm"
              onClick={() => setIsDatePickerOpen(true)}
              className="rounded-xl text-xs h-9 px-3 border-border hover:border-primary/50 cursor-pointer shadow-2xs font-semibold"
            >
              <CalendarDays className="h-4 w-4 mr-1.5 text-primary" />
              Change Date
            </Button>
          </div>
        </div>

        {/* Row 2: Quick Missed Days Shortcuts (Accessible Backfilling) */}
        {missedDaysList.length > 0 && (
          <div className="pt-3 border-t border-border/60">
            <div className="flex flex-wrap items-center gap-2">
              <span className="text-xs font-semibold text-muted-foreground flex items-center gap-1 shrink-0 mr-1">
                <Clock className="h-3.5 w-3.5 text-amber-600 dark:text-amber-400" />
                Missed Days to Backfill:
              </span>

              {missedDaysList.slice(0, 5).map((missed) => {
                const isSelected = missed.date === currentDate
                const parsedMissed = parseISO(missed.date)
                return (
                  <button
                    key={missed.date}
                    type="button"
                    onClick={() => handleSwitchDate(missed.date)}
                    className={cn(
                      "px-2.5 py-1 rounded-xl text-xs font-medium transition-all flex items-center gap-1.5 cursor-pointer border select-none",
                      isSelected
                        ? "bg-amber-500/20 text-amber-800 dark:text-amber-200 border-amber-500/50 shadow-2xs font-bold"
                        : "bg-muted/40 text-muted-foreground hover:text-foreground hover:bg-muted/70 border-border/70"
                    )}
                  >
                    <span>{format(parsedMissed, "EEE, MMM d")}</span>
                    <span
                      className={cn(
                        "px-1.5 py-0.2 rounded-full text-[10px] font-bold",
                        isSelected ? "bg-amber-600 text-white" : "bg-amber-500/15 text-amber-700 dark:text-amber-300"
                      )}
                    >
                      {missed.missingClassroomIds.length} left
                    </span>
                  </button>
                )
              })}

              {missedDaysList.length > 5 && (
                <button
                  type="button"
