import { AdminPageHeader } from "@/components/features/admin/admin-page-header"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Textarea } from "@/components/ui/textarea"
import type { ChecklistItem, User } from "@/lib/types"
import { getChecklistItems, addChecklistItem, updateChecklistItem, deleteChecklistItem } from "@/lib/supabase-data"
import { getAllUsers } from "@/app/actions/user-actions"
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "@/components/ui/dropdown-menu"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Pencil, Trash2, Plus, MoreVertical, LayoutList, GripVertical, CheckCircle2, AlertCircle } from "lucide-react"
import { useToast } from "@/components/ui/use-toast"

interface ChecklistManagerProps {
  currentUser: User
}

interface ChecklistItemFormData {
  title: string
  description: string
  points: number
  category: string
  displayOrder: number
  assignedSupervisorIds: string[]
}

function useChecklistManagerController({ currentUser }: ChecklistManagerProps) {
  const [items, setItems] = useState<ChecklistItem[]>([])
  const [loading, setLoading] = useState(true)
  const [isAddOpen, setIsAddOpen] = useState(false)
  const [isEditOpen, setIsEditOpen] = useState(false)
  const [currentItem, setCurrentItem] = useState<ChecklistItem | null>(null)
  const { toast } = useToast()

  const [formData, setFormData] = useState<ChecklistItemFormData>({
    title: "",
    description: "",
    points: 10,
    category: "General",
    displayOrder: 0,
    assignedSupervisorIds: []
  })
  const [supervisors, setSupervisors] = useState<User[]>([])

  const fetchItems = useCallback(
    async (signal?: AbortSignal) => {
      try {
        const [itemsData, usersResult] = await Promise.all([getChecklistItems(), getAllUsers()])
        if (signal?.aborted) return

        setItems(itemsData)

        if (usersResult.success) {
          const supervisorList = usersResult.data.filter((u: User) => u.role === "supervisor")
          setSupervisors(supervisorList)
        }
      } catch (error) {
        if (signal?.aborted) return
        console.error("Error fetching data:", error)
        toast({
          title: "Error",
          description: "Failed to load data",
          variant: "destructive"
        })
      } finally {
        if (!signal?.aborted) setLoading(false)
      }
    },
    [toast]
  )

  useEffect(() => {
    const controller = new AbortController()
    void fetchItems(controller.signal)
    return () => controller.abort()
  }, [fetchItems])

  const handleSave = async () => {
    if (!formData || !formData.title || !formData.title.trim()) {
      toast({
        title: "Validation Error",
        description: "Criterion title is required.",
        variant: "destructive"
      })
      return
    }

    if (!formData.points || formData.points <= 0) {
      toast({
        title: "Validation Error",
        description: "Points value must be at least 1.",
        variant: "destructive"
      })
      return
    }

    try {
      const result = await addChecklistItem(
        formData.title,
        formData.description,
        formData.points,
        formData.category,
        formData.displayOrder,
        undefined, // createdBy will be handled by RLS or backend
        formData.assignedSupervisorIds
      )

      if (result.success) {
        toast({
          title: "Success",
          description: "Checklist item added successfully"
        })
        setIsAddOpen(false)
        fetchItems()
        setFormData({
          title: "",
          description: "",
          points: 10,
          category: "General",
          displayOrder: 0,
          assignedSupervisorIds: []
        })
      } else {
        toast({
          title: "Error",
          description: result.error || "Failed to add item",
          variant: "destructive"
        })
      }
    } catch (error) {
      console.error("Error saving checklist item:", error)
      toast({
        title: "Error",
        description: "An unexpected error occurred",
        variant: "destructive"
      })
    }
  }

  const handleUpdate = async () => {
    if (!currentItem) return
    if (!formData || !formData.title || !formData.title.trim()) {
      toast({
        title: "Validation Error",
        description: "Criterion title is required.",
        variant: "destructive"
      })
      return
    }

    if (!formData.points || formData.points <= 0) {
      toast({
        title: "Validation Error",
        description: "Points value must be at least 1.",
        variant: "destructive"
      })
      return
    }

    try {
      const result = await updateChecklistItem(
        currentItem.id,
        formData.title,
        formData.description,
        formData.points,
        formData.category,
        formData.displayOrder,
        currentItem.is_active,
        formData.assignedSupervisorIds
      )

      if (result.success) {
        toast({
          title: "Success",
          description: "Checklist item updated successfully"
        })
        setIsEditOpen(false)
        setCurrentItem(null)
        fetchItems()
      } else {
        toast({
          title: "Error",
          description: result.error || "Failed to update item",
          variant: "destructive"
        })
      }
    } catch (error) {
      console.error("Error updating checklist item:", error)
      toast({
        title: "Error",
        description: "An unexpected error occurred",
        variant: "destructive"
      })
    }
  }

  const handleEdit = (item: ChecklistItem) => {
    setCurrentItem(item)
    setFormData({
      title: item.title,
      description: item.description || "",
      points: item.points,
      category: item.category || "General",
      displayOrder: item.display_order,
      assignedSupervisorIds: item.assigned_supervisors?.map((s) => s.id) || []
    })
    setIsEditOpen(true)
  }

  const handleDelete = async (id: string) => {
    if (!confirm("Are you sure you want to delete this item?")) return

    try {
      const result = await deleteChecklistItem(id)
      if (result.success) {
        toast({
          title: "Success",
          description: "Item deleted successfully"
        })
        fetchItems()
      } else {
        toast({
          title: "Error",
          description: result.error || "Failed to delete item",
          variant: "destructive"
        })
      }
    } catch (error) {
      console.error("Error deleting checklist item:", error)
      toast({
        title: "Error",
        description: "An unexpected error occurred",
        variant: "destructive"
      })
    }
  }

  const handleCancel = () => {
    setIsAddOpen(false)
    setIsEditOpen(false)
    setCurrentItem(null)
    setFormData({
      title: "",
      description: "",
      points: 10,
      category: "General",
      displayOrder: 0,
      assignedSupervisorIds: []
    })
  }

  const handleAddNew = () => {
    setFormData({
      title: "",
      description: "",
      points: 10,
      category: "General",
      displayOrder: 0,
      assignedSupervisorIds: []
    })
    setIsAddOpen(true)
  }

  const assignedSupervisorIds = useMemo(() => new Set(formData.assignedSupervisorIds), [formData.assignedSupervisorIds])
  return {
    assignedSupervisorIds,
    currentItem,
    formData,
    handleAddNew,
    handleCancel,
    handleDelete,
    handleEdit,
    handleSave,
    handleUpdate,
    isAddOpen,
    isEditOpen,
    items,
    loading,
    setFormData,
    supervisors
  }
}

