interface ClassroomManagementProps {
  currentUser: User
}

interface ClassroomFormData {
  name: string
  grade: string
  division: string
  description: string
  supervisorIds: string[]
}

function useClassroomManagementController({ currentUser }: ClassroomManagementProps) {
  const [classrooms, setClassrooms] = useState<Classroom[]>([])
  const [supervisors, setSupervisors] = useState<User[]>([])
  const [loading, setLoading] = useState(true)
  const [creating, setCreating] = useState(false)
  const [editingId, setEditingId] = useState<string | null>(null)
  const [isAdding, setIsAdding] = useState(false)
  const [selectedDivision, setSelectedDivision] = useState<string>("all")
  const [searchQuery, setSearchQuery] = useState<string>("")
  const [selectedClassrooms, setSelectedClassrooms] = useState<Set<string>>(new Set())
  const [bulkUpdating, setBulkUpdating] = useState(false)
  const { toast } = useToast()

  const [formData, setFormData] = useState<ClassroomFormData>({
    name: "",
    grade: "",
    division: "",
    description: "",
    supervisorIds: []
  })

  const loadClassrooms = useCallback(
    async (signal?: AbortSignal) => {
      try {
        const supabase = createClient()
        const { data, error } = await supabase
          .from("classrooms")
          .select(
            `
          *,
          classroom_supervisors!classroom_id(
            supervisor_id,
            users!classroom_supervisors_supervisor_id_fkey(id, name, email)
          )
        `
          )
          .eq("is_active", true)
          .order("name")
        if (signal?.aborted) return

        if (error) {
          console.error("Error fetching classrooms:", error)
          toast({
            title: "Error",
            description: "Failed to load classrooms",
            variant: "destructive"
          })
        } else {
          // Transform data to flatten the nested structure
          const transformedData = (data || []).map((classroom: any) => ({
            ...classroom,
            supervisors: classroom.classroom_supervisors?.map((s: any) => s.users) || []
          }))
          setClassrooms(transformedData)
        }
      } catch (error) {
        if (signal?.aborted) return
        console.error("Exception fetching classrooms:", error)
        toast({
          title: "Error",
          description: "Failed to load classrooms",
          variant: "destructive"
        })
      }
    },
    [toast]
  )

  const loadSupervisors = useCallback(async (signal?: AbortSignal) => {
    try {
      const result = await getAllUsers()
      if (signal?.aborted) return
      if (result.success) {
        // Filter to only supervisors
        const supervisorUsers = result.data.filter((user: any) => user.role === "supervisor")
        setSupervisors(supervisorUsers)
      } else {
        console.error("Failed to load supervisors:", result.error)
      }
    } catch (error) {
      if (signal?.aborted) return
      console.error("Error loading supervisors:", error)
    }
  }, [])

  useEffect(() => {
    const controller = new AbortController()
    async function init() {
      setLoading(true)
      try {
        await Promise.all([loadClassrooms(controller.signal), loadSupervisors(controller.signal)])
      } finally {
        setLoading((current) => (controller.signal.aborted ? current : false))
      }
    }
    void init()
    return () => controller.abort()
  }, [loadClassrooms, loadSupervisors])

  const handleSubmit = async () => {
    setCreating(true)

    const result = await createClassroom(
      formData.name,
      formData.grade,
      formData.division,
      formData.description,
      formData.supervisorIds
    )

    if (result.success) {
      toast({
        title: "Success",
        description: "Classroom created successfully"
      })
      setFormData({ name: "", grade: "", division: "", description: "", supervisorIds: [] })
      setIsAdding(false)
      loadClassrooms()
    } else {
      toast({
        title: "Error",
        description: result.error || "Failed to create classroom",
        variant: "destructive"
      })
    }

    setCreating(false)
  }

  const handleEdit = (classroom: Classroom) => {
    setEditingId(classroom.id)
    setFormData({
      name: classroom.name,
      grade: classroom.grade,
      division: classroom.division || "",
      description: classroom.description || "",
      supervisorIds: classroom.supervisors?.map((s) => s.id) || []
    })
    setIsAdding(false)
  }

  const handleUpdate = async () => {
    if (!editingId) return

    setCreating(true)

    const result = await updateClassroom(
      editingId,
      formData.name,
      formData.grade,
      formData.division,
      formData.description,
      formData.supervisorIds
    )

    if (result.success) {
      toast({
        title: "Success",
        description: "Classroom updated successfully"
      })
      setEditingId(null)
      setFormData({ name: "", grade: "", division: "", description: "", supervisorIds: [] })
      loadClassrooms()
    } else {
      toast({
        title: "Error",
        description: result.error || "Failed to update classroom",
        variant: "destructive"
      })
    }

    setCreating(false)
  }

  const handleDelete = async (classroomId: string) => {
    if (!confirm("Are you sure you want to deactivate this classroom?")) return

    const result = await deleteClassroom(classroomId)

    if (result.success) {
      toast({
        title: "Success",
        description: "Classroom deactivated successfully"
      })
      loadClassrooms()
    } else {
      toast({
        title: "Error",
        description: result.error || "Failed to deactivate classroom",
        variant: "destructive"
      })
    }
  }

  const handleCancel = () => {
    setEditingId(null)
    setIsAdding(false)
    setFormData({ name: "", grade: "", division: "", description: "", supervisorIds: [] })
  }

  const handleToggleSelect = (classroomId: string) => {
    const newSelected = new Set(selectedClassrooms)
    if (newSelected.has(classroomId)) {
      newSelected.delete(classroomId)
    } else {
      newSelected.add(classroomId)
    }
    setSelectedClassrooms(newSelected)
  }

  const handleSelectAll = () => {
    if (selectedClassrooms.size === filteredClassrooms.length) {
      setSelectedClassrooms(new Set())
    } else {
      setSelectedClassrooms(new Set(filteredClassrooms.map((c) => c.id)))
    }
  }

  const handleBulkUpdateDivision = async (division: string) => {
    if (selectedClassrooms.size === 0) {
      toast({
        title: "No Selection",
        description: "Please select at least one classroom",
        variant: "destructive"
      })
      return
    }

    setBulkUpdating(true)
    try {
      const result = await bulkUpdateClassroomDivisions(Array.from(selectedClassrooms), division)

      if (result.success) {
        toast({
          title: "Success",
          description: `Updated division for ${result.updatedCount || selectedClassrooms.size} classroom(s)`
        })
        setSelectedClassrooms(new Set())
        loadClassrooms()
      } else {
        toast({
          title: "Error",
          description: result.error || "Failed to update divisions",
          variant: "destructive"
        })
      }
    } catch (error) {
      console.error("handleBulkUpdateDivision failed:", error)
    } finally {
      setBulkUpdating(false)
    }
  }

  const handleQuickDivisionChange = async (classroomId: string, division: string) => {
    const classroom = classrooms.find((c) => c.id === classroomId)
    if (!classroom) return

    setBulkUpdating(true)
    try {
      const result = await bulkUpdateClassroomDivisions([classroomId], division)

      if (result.success) {
        toast({
          title: "Success",
          description: "Division updated successfully"
        })
        loadClassrooms()
      } else {
        toast({
          title: "Error",
          description: result.error || "Failed to update division",
          variant: "destructive"
        })
      }
    } catch (error) {
      console.error("handleQuickDivisionChange failed:", error)
    } finally {
      setBulkUpdating(false)
    }
  }

  const handleAddNew = () => {
    setIsAdding(true)
    setEditingId(null)
    setFormData({ name: "", grade: "", division: "", description: "", supervisorIds: [] })
  }

  const selectedSupervisorIds = useMemo(() => new Set(formData.supervisorIds), [formData.supervisorIds])

  // Filter classrooms by division and normalized search query across name, grade, and all supervisors
  const filteredClassrooms = useMemo(
    () => filterClassroomDirectory(classrooms, selectedDivision, searchQuery),
    [classrooms, selectedDivision, searchQuery]
  )

  // Clear selection when filter or search changes
  useEffect(() => {
    setSelectedClassrooms(new Set())
  }, [selectedDivision, searchQuery])
  return {
    bulkUpdating,
    creating,
    editingId,
    filteredClassrooms,
    formData,
    handleAddNew,
    handleBulkUpdateDivision,
    handleCancel,
    handleDelete,
    handleEdit,
    handleQuickDivisionChange,
    handleSelectAll,
    handleSubmit,
    handleToggleSelect,
    handleUpdate,
    isAdding,
    loading,
    searchQuery,
    selectedClassrooms,
    selectedDivision,
    selectedSupervisorIds,
    setFormData,
    setSearchQuery,
    setSelectedClassrooms,
    setSelectedDivision,
    supervisors
  }
}

