function filterClassroomDirectory(classrooms: Classroom[], selectedDivision: string, searchQuery: string) {
  const query = searchQuery.trim().toLowerCase()
  return classrooms.filter((classroom) => {
    if (selectedDivision !== "all" && classroom.division !== selectedDivision) return false
    if (!query) return true
    return (
      classroom.name.toLowerCase().includes(query) ||
      classroom.grade.toLowerCase().includes(query) ||
      !!classroom.supervisors?.some((supervisor) => supervisor.name.toLowerCase().includes(query))
    )
  })
}

