              </DialogTitle>
              <DialogDescription className="text-xs">
                Grade {inspectedEvaluation?.classroom?.grade || inspectedEvaluation?.classroom_grade}
                {(inspectedEvaluation?.classroom?.division || inspectedEvaluation?.classroom_division) &&
