                🟢 Live Active
              </Badge>
            )}
          </div>
        </DialogHeader>

        {inspectedEvaluation && (
          <EvaluationScoreBreakdown checklistMap={checklistMap} inspectedEvaluation={inspectedEvaluation} />
        )}

        <DialogFooter className="p-4 border-t border-border/60 bg-muted/10 flex flex-row items-center justify-between gap-2">
