    <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3 pt-3 border-t border-border/40 mt-3">
      {/* Scope Selector */}
      <div className="flex items-center bg-muted/60 p-1 rounded-xl border border-border/60 flex-wrap gap-1">
        <button
          type="button"
          onClick={() => setViewScope("all")}
          className={`min-h-9 px-3 py-1 text-xs rounded-lg font-medium transition-[color,background-color,border-color,box-shadow] cursor-pointer ${
            viewScope === "all"
              ? "bg-background text-foreground shadow-xs font-semibold"
              : "text-muted-foreground hover:text-foreground"
          }`}
        >
          All ({combinedEvaluations.length})
        </button>
        <button
          type="button"
          onClick={() => setViewScope("active")}
          className={`min-h-9 px-3 py-1 text-xs rounded-lg font-medium transition-[color,background-color,border-color,box-shadow] cursor-pointer ${
            viewScope === "active"
              ? "bg-primary text-primary-foreground shadow-xs font-semibold"
              : "text-muted-foreground hover:text-foreground"
          }`}
        >
          🟢 Live Active ({activeEvaluations.length})
        </button>
        <button
          type="button"
          onClick={() => setViewScope("archived")}
          className={`min-h-9 px-3 py-1 text-xs rounded-lg font-medium transition-[color,background-color,border-color,box-shadow] cursor-pointer ${
            viewScope === "archived"
              ? "bg-amber-600 text-white shadow-xs font-semibold"
              : "text-muted-foreground hover:text-foreground"
          }`}
        >
          📦 Archived ({archivedEvaluations.length})
        </button>
        <button
          type="button"
          onClick={() => setViewScope("undo_log")}
          className={`min-h-9 px-3 py-1 text-xs rounded-lg font-medium transition-[color,background-color,border-color,box-shadow] cursor-pointer flex items-center gap-1.5 ${
            viewScope === "undo_log"
              ? "bg-destructive text-destructive-foreground shadow-xs font-semibold"
              : "text-muted-foreground hover:text-foreground"
          }`}
        >
          <RotateCcw className="h-3 w-3" />
          Undo Log ({undoLogs.length})
        </button>
      </div>

      {viewScope !== "active" && viewScope !== "undo_log" && (
        <select
          aria-label="Evaluation month"
          value={monthFilter}
          onChange={(event) => setMonthFilter(event.target.value)}
          className="min-h-11 rounded-xl border border-border bg-background px-3 text-sm"
        >
          <option value="all">All months</option>
          {Array.from(
            new Set(combinedEvaluations.map((evaluation) => getSchoolMonthKey(new Date(evaluation.evaluation_date))))
          )
            .sort()
            .reverse()
            .map((key) => (
              <option key={key} value={key}>
                {key}
              </option>
            ))}
        </select>
      )}
      {/* Division Pills & Sorting Controls */}
      <div className="flex items-center flex-wrap gap-2">
        <div className="flex flex-wrap gap-1">
          <Button
            size="sm"
            variant={divisionFilter === "all" ? "default" : "outline"}
            onClick={() => setDivisionFilter("all")}
            className="h-8 text-[11px] rounded-full px-2.5 cursor-pointer"
          >
            All Divisions
          </Button>
          {DIVISION_OPTIONS.map((d) => (
            <Button
              key={d.value}
              size="sm"
              variant={divisionFilter.toLowerCase() === d.value.toLowerCase() ? "default" : "outline"}
              onClick={() => setDivisionFilter(d.value)}
              className="h-8 text-[11px] rounded-full px-2.5 cursor-pointer"
            >
              {d.label}
            </Button>
          ))}
        </div>

        {/* Sort Selector */}
        {viewScope !== "undo_log" && (
          <div className="flex items-center gap-1 bg-muted/60 p-0.5 rounded-lg border border-border/60 text-xs">
            <span className="text-[10px] text-muted-foreground px-2">Sort:</span>
            <select
              aria-label="Sort evaluations"
              value={sortBy}
              onChange={(e) => setSortBy(e.target.value as any)}
              className="bg-transparent text-xs font-medium text-foreground py-1 pr-2 rounded focus:outline-hidden cursor-pointer"
            >
              <option value="date_desc" className="bg-popover text-popover-foreground">
                Newest Date
              </option>
              <option value="date_asc" className="bg-popover text-popover-foreground">
                Oldest Date
              </option>
              <option value="score_desc" className="bg-popover text-popover-foreground">
                Highest Score
              </option>
              <option value="score_asc" className="bg-popover text-popover-foreground">
                Lowest Score
              </option>
            </select>
          </div>
        )}
      </div>
    </div>
  )
}

function UndoHistoryList({
