  buildWeeklyTrackingWorkbook,
  buildMonthlyTrackingWorkbook
} from "@/lib/excel/submission-tracking-excel"
import { downloadWorkbookBuffer } from "@/lib/excel/excel-design-tokens"

interface SubmissionTrackingProps {
  currentUser?: User
}

export function SubmissionTracking(props: SubmissionTrackingProps) {
  return <SubmissionTrackingContent {...props} />
}

function useSubmissionTrackingContentController({ currentUser }: SubmissionTrackingProps) {
  const { toast } = useToast()
  const [date, setDate] = useState<Date>(() => new Date())
  const [viewType, setViewType] = useState<"daily" | "weekly" | "monthly" | "custom">("daily")
  const [customStartDate, setCustomStartDate] = useState<string>(() => format(startOfMonth(new Date()), "yyyy-MM-dd"))
  const [customEndDate, setCustomEndDate] = useState<string>(() => format(endOfMonth(new Date()), "yyyy-MM-dd"))
  const [sortBy, setSortBy] = useState<"name" | "score" | "time">("time")
  const [classrooms, setClassrooms] = useState<Classroom[]>([])
  const [evaluations, setEvaluations] = useState<Evaluation[]>([])
  const [loading, setLoading] = useState(true)
  const [searchTerm, setSearchTerm] = useState("")
  const deferredSearch = useDeferredValue(searchTerm)
  const [selectedDivision, setSelectedDivision] = useState<string>("all")
  const [exporting, setExporting] = useState(false)
  const [exceptions, setExceptions] = useState<CalendarException[]>([])
  const [termDates, setTermDates] = useState<SchoolTermDates | null>(null)

  const fetchData = useCallback(
    async (signal?: AbortSignal) => {
      setLoading(true)
      try {
        const period = getTrackingDateRange(viewType, date, customStartDate, customEndDate)
        if (!period) return
        const { startDate, endDate } = period
        if (viewType === "custom" && customStartDate > customEndDate) {
          setCustomStartDate(startDate)
          setCustomEndDate(endDate)
          return
        }

        const [classroomsData, evaluationsData, exceptionsRes, termRes] = await Promise.all([
          getClassrooms(),
          getEvaluationsByDateRange(startDate, endDate),
          getCalendarExceptions(),
          getSchoolTermDates()
        ])
        if (signal?.aborted) return

        setClassrooms(classroomsData)
        setEvaluations(evaluationsData)
        if (exceptionsRes.success && exceptionsRes.data) {
          setExceptions(exceptionsRes.data)
        }
        if (termRes.success && termRes.data) {
          setTermDates(termRes.data)
        }
      } catch (error) {
        if (signal?.aborted) return
        console.error("Error fetching tracking data:", error)
        toast({
          title: "Error",
          description: "Failed to fetch submission data",
          variant: "destructive"
        })
      } finally {
        setLoading((current) => (signal?.aborted ? current : false))
      }
    },
    [date, viewType, customStartDate, customEndDate, toast]
  )

  useEffect(() => {
    const controller = new AbortController()
    void fetchData(controller.signal)
    return () => controller.abort()
  }, [fetchData])

  const filteredClassrooms = useMemo(() => {
    let filtered = classrooms
    if (selectedDivision !== "all") {
      filtered = filtered.filter((c) => c.division === selectedDivision)
    }
    if (deferredSearch) {
      const term = deferredSearch.toLowerCase()
      filtered = filtered.filter(
        (c) =>
          c.name.toLowerCase().includes(term) ||
          c.grade.toLowerCase().includes(term) ||
          c.supervisors?.some((s) => s.name.toLowerCase().includes(term))
      )
    }
    return filtered
  }, [classrooms, selectedDivision, deferredSearch])

  const exceptionMap = useMemo(() => {
    return new Map<string, CalendarException>(exceptions.map((e) => [e.exception_date, e]))
  }, [exceptions])

  const isWorkingSchoolDay = useCallback(
    (d: Date | string) => {
      const dateObj = typeof d === "string" ? new Date(d) : d
      if (isWeekend(dateObj)) return false
      const dateStr = format(dateObj, "yyyy-MM-dd")
      if (exceptionMap.has(dateStr)) return false
      if (termDates?.startDate && dateStr < termDates.startDate) return false
      if (termDates?.endDate && dateStr > termDates.endDate) return false
      return true
    },
    [exceptionMap, termDates]
  )

  const submissionStats = useMemo(
    () =>
      calculateTrackingSubmissionStats({
        filteredClassrooms,
        evaluations,
        viewType,
        date,
        customStartDate,
        customEndDate,
        exceptionMap,
        termDates,
        isWorkingSchoolDay
      }),
    [
      filteredClassrooms,
      evaluations,
      viewType,
      date,
      customStartDate,
      customEndDate,
      exceptionMap,
      termDates,
      isWorkingSchoolDay
    ]
  )

  // Synchronized sorting across all detailed lists
  const sortedClassroomPerformance = useMemo(
    () => sortTrackingPerformance(submissionStats, sortBy, evaluations),
    [submissionStats, sortBy, evaluations]
  )

  const handleExportExcel = async () => {
    setExporting(true)
    try {
      const { workbook, fileName } = await buildTrackingExport({
        viewType,
        date,
        filteredClassrooms,
        evaluations,
        submissionStats,
        sortedClassroomPerformance,
        customStartDate,
        customEndDate,
        isWorkingSchoolDay
      })

      const buffer = await workbook.xlsx.writeBuffer()
      downloadWorkbookBuffer(buffer, fileName)

      toast({
        title: "Export Complete",
        description: `Exported ${fileName} with per-division sheets.`
      })
    } catch (error: any) {
      console.error("Excel generation error:", error)
      toast({
        title: "Export Failed",
        description: error?.message || "Failed to generate Excel file",
        variant: "destructive"
      })
    } finally {
      setExporting(false)
    }
  }
  return {
    customEndDate,
    customStartDate,
    date,
    evaluations,
    exporting,
    filteredClassrooms,
    handleExportExcel,
    loading,
    searchTerm,
    selectedDivision,
    setCustomEndDate,
    setCustomStartDate,
    setDate,
    setSearchTerm,
    setSelectedDivision,
    setSortBy,
    setViewType,
    sortBy,
    sortedClassroomPerformance,
    submissionStats,
    viewType
  }
}

function SubmissionTrackingContent({ currentUser }: SubmissionTrackingProps) {
  const {
    customEndDate,
    customStartDate,
    date,
    evaluations,
    exporting,
    filteredClassrooms,
    handleExportExcel,
    loading,
    searchTerm,
    selectedDivision,
    setCustomEndDate,
    setCustomStartDate,
    setDate,
    setSearchTerm,
    setSelectedDivision,
    setSortBy,
    setViewType,
    sortBy,
    sortedClassroomPerformance,
    submissionStats,
    viewType
  } = useSubmissionTrackingContentController({ currentUser })

  return (
    <SubmissionTrackingMetrics
      currentUser={currentUser}
      customEndDate={customEndDate}
      customStartDate={customStartDate}
      date={date}
      evaluations={evaluations}
      exporting={exporting}
      filteredClassrooms={filteredClassrooms}
      handleExportExcel={handleExportExcel}
      loading={loading}
      searchTerm={searchTerm}
      selectedDivision={selectedDivision}
      setCustomEndDate={setCustomEndDate}
      setCustomStartDate={setCustomStartDate}
      setDate={setDate}
      setSearchTerm={setSearchTerm}
      setSelectedDivision={setSelectedDivision}
      setSortBy={setSortBy}
      setViewType={setViewType}
      sortBy={sortBy}
      sortedClassroomPerformance={sortedClassroomPerformance}
      submissionStats={submissionStats}
      viewType={viewType}
    />
  )
}

function calculateTrackingSubmissionStats({
  filteredClassrooms,
  evaluations,
  viewType,
  date,
  customStartDate,
  customEndDate,
  exceptionMap,
  termDates,
  isWorkingSchoolDay
}: {
  filteredClassrooms: Classroom[]
  evaluations: Evaluation[]
  viewType: "daily" | "weekly" | "monthly" | "custom"
  date: Date
  customStartDate: string
  customEndDate: string
  exceptionMap: Map<string, CalendarException>
  termDates: SchoolTermDates | null
  isWorkingSchoolDay: (d: Date | string) => boolean
}) {
  if (viewType === "daily") {
    const selectedDateStr = format(date, "yyyy-MM-dd")
    const dayException = exceptionMap.get(selectedDateStr)
    const isSelectedWeekend = isWeekend(date)
    const isOutsideTerm = termDates && (selectedDateStr < termDates.startDate || selectedDateStr > termDates.endDate)
    const isNonWorkingDay = isSelectedWeekend || !!dayException || !!isOutsideTerm
    const nonWorkingReason =
      dayException?.reason ||
      (isSelectedWeekend ? "Weekend" : isOutsideTerm ? "Outside Academic Term" : "Calendar Exception")

    const submittedIds = new Set(evaluations.map((e) => e.classroom_id))
    const submitted = filteredClassrooms.filter((c) => submittedIds.has(c.id))
    // On non-working days / calendar exceptions, no classroom is penalized as missing
    const notSubmitted = isNonWorkingDay ? [] : filteredClassrooms.filter((c) => !submittedIds.has(c.id))

    return {
      submitted,
      notSubmitted,
      rate: isNonWorkingDay
        ? 100
        : filteredClassrooms.length > 0
          ? (submitted.length / filteredClassrooms.length) * 100
          : 0,
      isNonWorkingDay,
      nonWorkingReason,
      excludedExceptionsCount: isNonWorkingDay ? 1 : 0
    }
  } else if (viewType === "weekly") {
    const start = startOfWeek(date, { weekStartsOn: 1 })
    const rawDays = Array.from({ length: 5 }, (_, i) => addDays(start, i))

    const weeklyDays = rawDays.map((d) => {
      const dStr = format(d, "yyyy-MM-dd")
      const exc = exceptionMap.get(dStr)
      const isOutside = termDates && (dStr < termDates.startDate || dStr > termDates.endDate)
      const isException = !!exc || !!isOutside
      const reason = exc?.reason || (isOutside ? "Outside Term" : undefined)
      return {
        date: d,
        dateStr: dStr,
        isException,
        reason
      }
    })

    const activeDays = weeklyDays.filter((d) => !d.isException)
    const totalDays = activeDays.length
    const excludedExceptionsCount = weeklyDays.filter((d) => d.isException).length

    const classroomPerformance = filteredClassrooms.map((c) => {
      const classEvals = evaluations.filter((e) => e.classroom_id === c.id)
      const submittedDays = new Set(classEvals.map((e) => format(new Date(e.evaluation_date), "yyyy-MM-dd")))

      const submittedCount = activeDays.filter((d) => submittedDays.has(d.dateStr)).length

      return {
        classroom: c,
        submittedCount,
        totalDays,
        rate: totalDays > 0 ? (submittedCount / totalDays) * 100 : 100,
        workDays: weeklyDays.map((d) => ({
          date: d.date,
          isSubmitted: submittedDays.has(d.dateStr),
          isException: d.isException,
          reason: d.reason
        }))
      }
    })

    return {
      classroomPerformance,
      excludedExceptionsCount,
      avgRate:
        classroomPerformance.length > 0
          ? classroomPerformance.reduce((sum, p) => sum + p.rate, 0) / classroomPerformance.length
          : 0
    }
  } else if (viewType === "monthly") {
    // Monthly stats synced with calendar exceptions
    const allDays = eachDayOfInterval({
      start: startOfMonth(date),
      end: endOfMonth(date)
    })

    const allWeekdays = allDays.filter((d) => !isWeekend(d))
    const activeDays = allDays.filter((d) => isWorkingSchoolDay(d))
    const totalDays = activeDays.length
    const activeDateStrs = new Set(activeDays.map((d) => format(d, "yyyy-MM-dd")))
    const excludedExceptionsCount = Math.max(0, allWeekdays.length - totalDays)

    const classroomPerformance = filteredClassrooms.map((c) => {
      const classEvals = evaluations.filter((e) => e.classroom_id === c.id)
      const submittedDays = new Set(classEvals.map((e) => format(new Date(e.evaluation_date), "yyyy-MM-dd")))

      // Only count submissions that fall on active school days
      const submittedCount = Array.from(submittedDays).filter((dStr) => activeDateStrs.has(dStr)).length

      return {
        classroom: c,
        submittedCount,
        totalDays,
        rate: totalDays > 0 ? (submittedCount / totalDays) * 100 : 100
      }
    })

    return {
      classroomPerformance,
      excludedExceptionsCount,
      avgRate:
        classroomPerformance.length > 0
          ? classroomPerformance.reduce((sum, p) => sum + p.rate, 0) / classroomPerformance.length
          : 0
    }
  } else {
    // Custom Date Range stats synced with calendar exceptions
    let startD = new Date(customStartDate)
    let endD = new Date(customEndDate)
    if (isNaN(startD.getTime())) startD = startOfMonth(new Date())
    if (isNaN(endD.getTime())) endD = endOfMonth(new Date())

    if (startD > endD) [startD, endD] = [endD, startD]
    const allCustomDays = eachDayOfInterval({
      start: startD,
      end: endD
    })

    const allWeekdays = allCustomDays.filter((d) => !isWeekend(d))
    const activeDays = allCustomDays.filter((d) => isWorkingSchoolDay(d))
    const totalDays = activeDays.length
    const activeDateStrs = new Set(activeDays.map((d) => format(d, "yyyy-MM-dd")))
    const excludedExceptionsCount = Math.max(0, allWeekdays.length - totalDays)

    const classroomPerformance = filteredClassrooms.map((c) => {
      const classEvals = evaluations.filter((e) => e.classroom_id === c.id)
      const submittedDays = new Set(classEvals.map((e) => format(new Date(e.evaluation_date), "yyyy-MM-dd")))
      const submittedCount = Array.from(submittedDays).filter((dStr) => activeDateStrs.has(dStr)).length

      return {
        classroom: c,
        submittedCount,
        totalDays,
        rate: totalDays > 0 ? (submittedCount / totalDays) * 100 : 100
      }
    })

    return {
      classroomPerformance,
      excludedExceptionsCount,
      avgRate:
        classroomPerformance.length > 0
          ? classroomPerformance.reduce((sum, p) => sum + p.rate, 0) / classroomPerformance.length
          : 0
    }
  }
}

function getTrackingDateRange(viewType: string, date: Date, customStartDate: string, customEndDate: string) {
  if (viewType === "daily") {
    const selectedDate = format(date, "yyyy-MM-dd")
    return { startDate: selectedDate, endDate: selectedDate }
  }
  if (viewType === "weekly") {
    const start = startOfWeek(date, { weekStartsOn: 1 })
    return { startDate: format(start, "yyyy-MM-dd"), endDate: format(addDays(start, 4), "yyyy-MM-dd") }
  }
  if (viewType === "monthly") {
    return { startDate: format(startOfMonth(date), "yyyy-MM-dd"), endDate: format(endOfMonth(date), "yyyy-MM-dd") }
  }
  if (
    !customStartDate ||
    !customEndDate ||
    Number.isNaN(Date.parse(customStartDate)) ||
    Number.isNaN(Date.parse(customEndDate))
  )
    return null
  return customStartDate <= customEndDate
    ? { startDate: customStartDate, endDate: customEndDate }
    : { startDate: customEndDate, endDate: customStartDate }
}

async function buildTrackingExport({
  viewType,
  date,
  filteredClassrooms,
  evaluations,
  submissionStats,
  sortedClassroomPerformance,
  customStartDate,
  customEndDate,
  isWorkingSchoolDay
}: {
  viewType: string
  date: Date
  filteredClassrooms: Classroom[]
  evaluations: Evaluation[]
  submissionStats: ReturnType<typeof calculateTrackingSubmissionStats>
  sortedClassroomPerformance: any[]
  customStartDate: string
  customEndDate: string
  isWorkingSchoolDay: (date: Date | string) => boolean
}) {
  let workbook: any
  let fileName = ""

  if (viewType === "daily") {
    const submittedList = (submissionStats as any)?.submitted || []
    const notSubmittedList = (submissionStats as any)?.notSubmitted || []
    workbook = await buildDailyTrackingWorkbook({
      date,
      classrooms: filteredClassrooms,
      evaluations,
      submittedList,
      notSubmittedList
    })
    fileName = `RHHS_Daily_Submission_Audit_${format(date, "yyyy-MM-dd")}.xlsx`
  } else if (viewType === "weekly") {
    workbook = await buildWeeklyTrackingWorkbook(date, filteredClassrooms, evaluations)
    const weekStart = startOfWeek(date, { weekStartsOn: 1 })
    fileName = `RHHS_Green_Rankings_Week_${format(weekStart, "yyyy-MM-dd")}.xlsx`
  } else if (viewType === "monthly") {
    const daysInMonth = eachDayOfInterval({
      start: startOfMonth(date),
      end: endOfMonth(date)
    })
    const workdays = daysInMonth.filter((d) => isWorkingSchoolDay(d))
    workbook = await buildMonthlyTrackingWorkbook({
      date,
      classrooms: filteredClassrooms,
      workdays,
      performanceList: sortedClassroomPerformance
    })
    fileName = `RHHS_Monthly_Submission_Audit_${format(date, "yyyy-MM")}.xlsx`
  } else {
    // Custom Date Range Export
    let startD = new Date(customStartDate)
    let endD = new Date(customEndDate)
    if (isNaN(startD.getTime())) startD = startOfMonth(new Date())
    if (isNaN(endD.getTime())) endD = endOfMonth(new Date())

    const customDays = eachDayOfInterval({
      start: startD,
      end: endD
    })
    const workdays = customDays.filter((d) => isWorkingSchoolDay(d))
    workbook = await buildMonthlyTrackingWorkbook({
      date: startD,
      classrooms: filteredClassrooms,
      workdays,
      performanceList: sortedClassroomPerformance
    })
    fileName = `RHHS_Custom_Submission_Audit_${format(startD, "yyyy-MM-dd")}_to_${format(endD, "yyyy-MM-dd")}.xlsx`
  }

  return { workbook, fileName }
}

function sortTrackingPerformance(
  submissionStats: ReturnType<typeof calculateTrackingSubmissionStats>,
  sortBy: string,
  evaluations: Evaluation[]
) {
  const perf = (submissionStats as any).classroomPerformance || []
  return [...perf].sort((a: any, b: any) => {
    if (sortBy === "name") {
      return a.classroom.name.localeCompare(b.classroom.name)
    } else if (sortBy === "score") {
      const rateA = a.rate !== undefined ? a.rate : a.submittedCount / (a.totalDays || 1)
      const rateB = b.rate !== undefined ? b.rate : b.submittedCount / (b.totalDays || 1)
      return rateB - rateA
    } else {
      // Latest evaluation date
      const classEvalsA = evaluations.filter((e) => e.classroom_id === a.classroom.id)
      const classEvalsB = evaluations.filter((e) => e.classroom_id === b.classroom.id)

      const lastDateA =
        classEvalsA.length > 0 ? Math.max(...classEvalsA.map((e) => new Date(e.evaluation_date).getTime())) : 0
      const lastDateB =
        classEvalsB.length > 0 ? Math.max(...classEvalsB.map((e) => new Date(e.evaluation_date).getTime())) : 0

      return lastDateB - lastDateA
    }
  })
}

function SubmissionTrackingControls({
  customEndDate,
  customStartDate,
  date,
  searchTerm,
  selectedDivision,
  setCustomEndDate,
  setCustomStartDate,
  setDate,
  setSearchTerm,
  setSelectedDivision,
  setSortBy,
  setViewType,
  sortBy,
  viewType
}: Pick<
  ReturnType<typeof useSubmissionTrackingContentController>,
  | "customEndDate"
  | "customStartDate"
  | "date"
  | "searchTerm"
  | "selectedDivision"
  | "setCustomEndDate"
  | "setCustomStartDate"
  | "setDate"
  | "setSearchTerm"
  | "setSelectedDivision"
  | "setSortBy"
  | "setViewType"
  | "sortBy"
  | "viewType"
>) {
  return (
    <Card className="lg:col-span-1 h-fit">
      <CardHeader>
        <CardTitle className="text-sm font-medium">Tracking Controls</CardTitle>
      </CardHeader>
      <CardContent className="space-y-6">
        <div className="space-y-2">
          <span className="text-xs font-medium text-muted-foreground" id="tracking-view-type-label">
            View Type
          </span>
          <Tabs
            aria-labelledby="tracking-view-type-label"
            value={viewType}
            onValueChange={(v) => setViewType(v as any)}
            className="w-full"
          >
            <TabsList className="grid grid-cols-4 w-full">
              <TabsTrigger value="daily">Daily</TabsTrigger>
              <TabsTrigger value="weekly">Week</TabsTrigger>
              <TabsTrigger value="monthly">Month</TabsTrigger>
              <TabsTrigger value="custom">Range</TabsTrigger>
            </TabsList>
          </Tabs>
        </div>

        {viewType !== "custom" ? (
          <div className="space-y-2">
            <label className="text-xs font-medium text-muted-foreground" htmlFor="tracking-date">
              {viewType === "daily" ? "Select Date" : viewType === "weekly" ? "Select Week" : "Select Month"}
            </label>
            <div className="relative">
              <Calendar className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground pointer-events-none" />
              <Input
                id="tracking-date"
                type={viewType === "monthly" ? "month" : "date"}
                className="pl-8"
                value={format(date, viewType === "monthly" ? "yyyy-MM" : "yyyy-MM-dd")}
                onChange={(e) => {
                  if (!e.target.value) return
                  const val = e.target.value
                  const newDate = viewType === "monthly" ? new Date(`${val}-01T12:00:00`) : new Date(`${val}T12:00:00`)
                  if (!isNaN(newDate.getTime())) {
                    setDate(newDate)
                  }
                }}
              />
            </div>
            {viewType === "weekly" && (
              <p className="text-[10px] text-muted-foreground mt-1">
                Week of {format(startOfWeek(date, { weekStartsOn: 1 }), "MMM d")} -{" "}
                {format(addDays(startOfWeek(date, { weekStartsOn: 1 }), 4), "MMM d")}
              </p>
            )}
          </div>
        ) : (
          <div className="space-y-3">
            <div className="space-y-1.5">
              <label className="text-xs font-medium text-muted-foreground" htmlFor="tracking-start-date">
                From Date
              </label>
              <Input
                id="tracking-start-date"
                type="date"
                value={customStartDate}
                onChange={(e) => setCustomStartDate(e.target.value)}
              />
            </div>
            <div className="space-y-1.5">
              <label className="text-xs font-medium text-muted-foreground" htmlFor="tracking-end-date">
                To Date
              </label>
              <Input
                id="tracking-end-date"
                type="date"
                value={customEndDate}
                onChange={(e) => setCustomEndDate(e.target.value)}
              />
            </div>
          </div>
        )}

        <div className="space-y-2">
          <span className="text-xs font-medium text-muted-foreground" id="tracking-sort-label">
            Sort By
          </span>
          <Select aria-labelledby="tracking-sort-label" value={sortBy} onValueChange={(v) => setSortBy(v as any)}>
            <SelectTrigger>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="time">Latest First</SelectItem>
              <SelectItem value="score">Higher Rate First</SelectItem>
              <SelectItem value="name">Classroom Name</SelectItem>
            </SelectContent>
          </Select>
        </div>

        <div className="space-y-2">
          <span className="text-xs font-medium text-muted-foreground" id="tracking-division-label">
            Division Filter
          </span>
          <Select
            aria-labelledby="tracking-division-label"
            value={selectedDivision}
            onValueChange={setSelectedDivision}
          >
            <SelectTrigger>
              <div className="flex items-center">
                <Filter className="mr-2 h-4 w-4 text-muted-foreground" />
                <SelectValue placeholder="All Divisions" />
              </div>
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Divisions</SelectItem>
              {DIVISION_OPTIONS.map((opt) => (
                <SelectItem key={opt.value} value={opt.value}>
                  {opt.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        <div className="space-y-2">
          <label className="text-xs font-medium text-muted-foreground" htmlFor="tracking-search">
            Search
          </label>
          <div className="relative">
            <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
            <Input
              id="tracking-search"
              placeholder="Classroom or supervisor..."
              className="pl-8"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
        </div>
      </CardContent>
    </Card>
  )
}

function SubmissionTrackingRecords({
  customEndDate,
  customStartDate,
  date,
  evaluations,
  loading,
  sortBy,
  sortedClassroomPerformance,
  submissionStats,
  viewType
}: Pick<
  ReturnType<typeof useSubmissionTrackingContentController>,
  | "customEndDate"
  | "customStartDate"
  | "date"
  | "evaluations"
  | "loading"
  | "sortBy"
  | "sortedClassroomPerformance"
  | "submissionStats"
  | "viewType"
>) {
  return (
