              : viewType === "monthly"
                ? `Monthly Performance for ${format(date, "MMMM yyyy")}`
                : `Custom Period Tracking (${format(new Date(customStartDate), "MMM d, yyyy")} - ${format(new Date(customEndDate), "MMM d, yyyy")})`}
