            evaluations={evaluations}
            sortBy={sortBy}
            submissionStats={submissionStats}
          />
        ) : viewType === "weekly" ? (
          <WeeklySubmissionRecords date={date} sortedClassroomPerformance={sortedClassroomPerformance} />
        ) : (
          <PeriodSubmissionRecords sortedClassroomPerformance={sortedClassroomPerformance} viewType={viewType} />
        )}
      </CardContent>
    </Card>
  )
}

function DailySubmissionRecords({
  date,
  evaluations,
  sortBy,
  submissionStats
}: Pick<
  NonNullable<Parameters<typeof SubmissionTrackingRecords>[0]>,
  "date" | "evaluations" | "sortBy" | "submissionStats"
>) {
  return (
    <div className="space-y-6">
      {/* Calendar Exception Notice */}
      {(submissionStats as any).isNonWorkingDay && (
        <div className="p-4 rounded-xl bg-blue-500/10 border border-blue-500/25 flex items-start gap-3">
          <CalendarOff className="h-5 w-5 text-blue-600 dark:text-blue-400 mt-0.5 shrink-0" />
          <div>
            <h4 className="text-sm font-bold text-foreground">
              School Calendar Exception Day ({format(date, "PPPP")})
            </h4>
            <p className="text-xs text-muted-foreground mt-0.5 leading-relaxed">
              Reason: <strong className="text-foreground">{(submissionStats as any).nonWorkingReason}</strong>. This
              date is marked in the school calendar as an excused exception. No supervisor evaluations are required, and
              no classrooms are penalized as missing.
            </p>
          </div>
        </div>
      )}

      {/* Submitted List */}
      <div className="space-y-3">
        <h3 className="text-sm font-semibold text-green-600 flex items-center gap-2">
          <CheckCircle2 className="h-4 w-4" />
          Submitted ({(submissionStats as any)?.submitted?.length ?? 0})
        </h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
          {(((submissionStats as any)?.submitted as Classroom[]) || [])
            .map((c: Classroom) => {
              const eval_ = evaluations.find((e) => e.classroom_id === c.id)
              return { classroom: c, evaluation: eval_ }
            })
            .sort((a: any, b: any) => {
              if (sortBy === "score") {
                return (b.evaluation?.total_score || 0) - (a.evaluation?.total_score || 0)
              } else if (sortBy === "name") {
                return a.classroom.name.localeCompare(b.classroom.name)
              } else {
                return (
                  new Date(b.evaluation?.created_at || 0).getTime() - new Date(a.evaluation?.created_at || 0).getTime()
                )
              }
            })
            .map(({ classroom: c, evaluation: eval_ }: any) => (
              <div
                key={c.id}
                className="p-3 rounded-lg border bg-card flex items-center justify-between transition-[background-color,border-color,color,box-shadow,opacity,transform] hover:bg-muted/30"
              >
                <div>
                  <p className="font-semibold text-sm">{c.name}</p>
                  <p className="text-xs text-muted-foreground mt-0.5">
                    Grade {c.grade} • {getDivisionDisplayName(c.division)}
                  </p>
                  <div className="flex items-center gap-1.5 mt-2">
                    <Users className="h-3 w-3 text-muted-foreground" />
                    <p className="text-[10px] text-muted-foreground">
                      {eval_?.supervisor?.name || c.supervisors?.[0]?.name || "Unknown"}
                    </p>
                  </div>
                </div>
                <div className="text-right">
                  <p className="text-sm font-bold text-primary">{eval_?.total_score} pts</p>
                  <p className="text-[10px] text-muted-foreground mt-0.5">
                    {eval_ ? format(new Date(eval_.created_at || ""), "p") : ""}
                  </p>
                </div>
              </div>
            ))}
        </div>
      </div>

      {/* Missing List - High Priority */}
      {!(submissionStats as any)?.isNonWorkingDay && ((submissionStats as any)?.notSubmitted?.length ?? 0) > 0 && (
        <div className="space-y-3">
          <h3 className="text-sm font-semibold text-destructive flex items-center gap-2">
            <XCircle className="h-4 w-4" />
            Not Submitted ({(submissionStats as any)?.notSubmitted?.length ?? 0})
          </h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
            {(((submissionStats as any)?.notSubmitted as Classroom[]) || []).map((c: Classroom) => (
              <div
                key={c.id}
                className="p-3 rounded-lg border border-destructive/20 bg-destructive/5 flex items-center justify-between transition-[background-color,border-color,color,box-shadow,opacity,transform] hover:bg-destructive/10"
              >
                <div>
                  <p className="font-semibold text-sm">{c.name}</p>
                  <p className="text-xs text-muted-foreground mt-0.5">
                    Grade {c.grade} • {getDivisionDisplayName(c.division)}
                  </p>
                  <div className="flex items-center gap-1.5 mt-2">
                    <Users className="h-3 w-3 text-muted-foreground" />
                    <p className="text-[10px] text-muted-foreground">
                      {c.supervisors?.map((s) => s.name).join(", ") || "No supervisor assigned"}
                    </p>
                  </div>
                </div>
                <span className="text-[10px] font-bold px-2.5 py-1 rounded-full bg-destructive/10 text-destructive border border-destructive/20">
                  Missing
