} from "@/components/ui/alert-dialog"
import { DIVISION_OPTIONS, getDivisionDisplayName } from "@/lib/division-display"
import Link from "next/link"

const DIVISIONS = DIVISION_OPTIONS.map((opt) => opt.value)
const MONTHS = [
  { value: 1, label: "January" },
  { value: 2, label: "February" },
  { value: 3, label: "March" },
  { value: 4, label: "April" },
  { value: 5, label: "May" },
  { value: 6, label: "June" },
  { value: 7, label: "July" },
  { value: 8, label: "August" },
  { value: 9, label: "September" },
  { value: 10, label: "October" },
  { value: 11, label: "November" },
  { value: 12, label: "December" }
]

function useMonthlyWinnersManagerController({ defaultMonth }: { defaultMonth?: DisplayMonth }) {
  const { toast } = useToast()
  const [loading, setLoading] = useState(true)
  const [loadError, setLoadError] = useState<string | null>(null)
  const [batchDeclaring, setBatchDeclaring] = useState(false)
  const [selectedYear, setSelectedYear] = useState(() => defaultMonth?.year ?? getSchoolMonth().year)
  const [selectedMonth, setSelectedMonth] = useState(() => defaultMonth?.month ?? getSchoolMonth().month)
  const [winners, setWinners] = useState<any[]>([])
  const [topClassrooms, setTopClassrooms] = useState<Record<string, any[]>>({})
  const [classrooms, setClassrooms] = useState<Classroom[]>([])
  const [deleteDialog, setDeleteDialog] = useState<{ open: boolean; winnerId: string; divisionName?: string }>({
    open: false,
    winnerId: ""
  })
  const [batchConfirmOpen, setBatchConfirmOpen] = useState(false)
  const [manualSelection, setManualSelection] = useState<Record<string, string>>({})
  const [changingDivision, setChangingDivision] = useState<string | null>(null)

  const requestRef = useRef(0)

  const loadData = useCallback(async () => {
    const requestId = ++requestRef.current
    setLoading(true)
    setLoadError(null)
    setWinners([])
    setTopClassrooms({})
    try {
      const [winnerResult, ...divisionResults] = await Promise.all([
        getMonthlyWinners(selectedYear, selectedMonth),
        ...DIVISIONS.map((division) => getTopClassroomsByDivision(division, selectedYear, selectedMonth))
      ])
      if (requestId !== requestRef.current) return
      if (!winnerResult.success) throw new Error(winnerResult.error || "Failed to load winners")
      const failed = divisionResults.find((result) => !result.success)
      if (failed) throw new Error(failed.error || "Failed to load standings")
      const standings: Record<string, any[]> = {}
      DIVISIONS.forEach((division, index) => {
        standings[division] = divisionResults[index].data || []
      })
      setWinners(
        (winnerResult.data || []).filter(
          (winner: any) => winner.year === selectedYear && winner.month === selectedMonth
        )
      )
      setTopClassrooms(standings)
    } catch (error) {
      if (requestId !== requestRef.current) return
      setLoadError("Declarations and standings could not be loaded. Please try again.")
      toast({
        title: "Unable to load competition",
        description: error instanceof Error ? error.message : "Please try again.",
        variant: "destructive"
      })
    } finally {
      if (requestId === requestRef.current) setLoading(false)
    }
  }, [selectedYear, selectedMonth, toast])

  useEffect(() => {
    let cancelled = false
    void getClassrooms().then((data) => {
      if (!cancelled) setClassrooms(data)
    })
    return () => {
      cancelled = true
    }
  }, [])

  useEffect(() => {
    void loadData()
    return () => {
      requestRef.current += 1
    }
  }, [loadData])

  const changePeriod = (year: number, month: number) => {
    requestRef.current += 1
    setLoading(true)
    setWinners([])
    setTopClassrooms({})
    setManualSelection({})
    setChangingDivision(null)
    setDeleteDialog({ open: false, winnerId: "" })
    setBatchConfirmOpen(false)
    setSelectedYear(year)
    setSelectedMonth(month)
  }

  const handleDeclareWinner = async (division: string, classroomData: any) => {
    if (!classroomData || !classroomData.classroom) return

    setLoading(true)
    let result
    try {
      result = await declareMonthlyWinner(
        classroomData.classroom.id,
        division,
        selectedYear,
        selectedMonth,
        classroomData.totalScore || 0,
        classroomData.averageScore || 0,
        classroomData.evaluationCount || 0
      )
    } finally {
      setLoading(false)
    }

    if (result.success) {
      toast({
        title: "Winner Declared!",
        description: `Successfully crowned ${classroomData.classroom.name} as ${getDivisionDisplayName(division)} Champion.`
      })
      setChangingDivision(null)
      void loadData()
    } else {
      toast({
        title: "Declaration Failed",
        description: result.error || "Failed to declare winner",
        variant: "destructive"
      })
    }
  }

  // Auto-Declare All #1 Leaders
  const handleAutoDeclareAllLeaders = async () => {
    setBatchDeclaring(true)
    let declaredCount = 0
    let failureCount = 0

    try {
      const winnersByDivision = new Map(winners.map((winner) => [winner.division, winner]))
      for (const division of DIVISIONS) {
        const existingWinner = winnersByDivision.get(division)
        if (existingWinner) continue // already declared

        const topContenders = topClassrooms[division] || []
        if (topContenders.length > 0) {
          const leader = topContenders[0]
          const res = await declareMonthlyWinner(
            leader.classroom.id,
            division,
            selectedYear,
            selectedMonth,
            leader.totalScore || 0,
            leader.averageScore || 0,
            leader.evaluationCount || 0
          )
          if (res.success) {
            declaredCount++
          } else {
            failureCount++
          }
        }
      }

      if (declaredCount > 0) {
        toast({
          title: "Auto-Declaration Complete",
          description: `Successfully declared ${declaredCount} division champions from top evaluations!`
        })
      } else if (failureCount === 0) {
        toast({
          title: "No Action Needed",
          description: "All divisions are already declared or lack evaluation records."
        })
      }

      await loadData()
    } catch (err: any) {
      toast({
        title: "Batch Declaration Error",
        description: err.message || "Failed to complete auto-declaration.",
        variant: "destructive"
      })
    } finally {
      setBatchDeclaring(false)
      setBatchConfirmOpen(false)
    }
  }

  const handleDeleteWinner = async () => {
    if (!deleteDialog.winnerId) return

    setLoading(true)
    let result
    try {
      result = await deleteMonthlyWinner(deleteDialog.winnerId)
    } finally {
      setLoading(false)
    }
    setDeleteDialog({ open: false, winnerId: "" })

    if (result.success) {
      toast({
        title: "Winner Removed",
        description: "The champion declaration has been removed."
      })
      void loadData()
    } else {
      toast({
        title: "Error",
        description: result.error || "Failed to delete winner",
        variant: "destructive"
      })
    }
  }

  const handleManualDeclare = (division: string) => {
    const classroomId = manualSelection[division]
    if (!classroomId) return

    const topClassroom = topClassrooms[division]?.find((c) => c.classroom.id === classroomId)
    if (topClassroom) {
      handleDeclareWinner(division, topClassroom)
    } else {
      const classroom = classrooms.find((c) => c.id === classroomId)
      if (classroom) {
        handleDeclareWinner(division, {
          classroom,
          totalScore: 0,
          averageScore: 0,
          evaluationCount: 0
        })
      }
    }

    setManualSelection((prev) => {
      const next = { ...prev }
      delete next[division]
      return next
    })
  }

  // Count unassigned divisions with eligible #1 leaders
  const unassignedWithLeaders = useMemo(() => {
    return DIVISIONS.filter((division) => {
      const isDeclared = winners.some((w) => w.division === division)
      const hasLeader = (topClassrooms[division] || []).length > 0
      return !isDeclared && hasLeader
    })
  }, [winners, topClassrooms])

  const declaredCount = winners.length
  const totalDivisions = DIVISIONS.length
  const progressPercent = Math.round((declaredCount / totalDivisions) * 100)
  const currentMonthLabel = MONTHS.find((m) => m.value === selectedMonth)?.label || ""

  const years = Array.from(
    new Set([selectedYear, ...Array.from({ length: 5 }, (_, i) => getSchoolMonth().year - i)])
  ).sort((a, b) => b - a)
  return {
    batchConfirmOpen,
    batchDeclaring,
    changePeriod,
    changingDivision,
    classrooms,
    currentMonthLabel,
    declaredCount,
    deleteDialog,
    handleAutoDeclareAllLeaders,
    handleDeclareWinner,
    handleDeleteWinner,
    handleManualDeclare,
    loadData,
    loadError,
    loading,
    manualSelection,
    progressPercent,
    selectedMonth,
    selectedYear,
    setBatchConfirmOpen,
    setChangingDivision,
    setDeleteDialog,
    setManualSelection,
    topClassrooms,
    totalDivisions,
    unassignedWithLeaders,
    winners,
    years
  }
}

export function MonthlyWinnersManager({ defaultMonth }: { defaultMonth?: DisplayMonth }) {
  const {
    batchConfirmOpen,
    batchDeclaring,
    changePeriod,
    changingDivision,
    classrooms,
    currentMonthLabel,
    declaredCount,
    deleteDialog,
    handleAutoDeclareAllLeaders,
    handleDeclareWinner,
    handleDeleteWinner,
