    loadError,
    loading,
    manualSelection,
    progressPercent,
    selectedMonth,
    selectedYear,
    setBatchConfirmOpen,
    setChangingDivision,
    setDeleteDialog,
    setManualSelection,
    topClassrooms,
    totalDivisions,
    unassignedWithLeaders,
    winners,
