function MonthlyDivisionDeclaration({
  division,
  batchDeclaring,
  changingDivision,
  classrooms,
  currentMonthLabel,
  handleDeclareWinner,
  handleManualDeclare,
  loading,
  manualSelection,
  selectedYear,
  setChangingDivision,
  setDeleteDialog,
  setManualSelection,
  topClassrooms,
  winners
}: Pick<
  ReturnType<typeof useMonthlyWinnersManagerController>,
  | "batchDeclaring"
  | "changingDivision"
  | "classrooms"
  | "currentMonthLabel"
  | "handleDeclareWinner"
  | "handleManualDeclare"
  | "loading"
  | "manualSelection"
  | "selectedYear"
  | "setChangingDivision"
  | "setDeleteDialog"
  | "setManualSelection"
  | "topClassrooms"
  | "winners"
> & { division: string }) {
  const winner = winners.find((w) => w.division === division)
  const topContenders = topClassrooms[division] || []
  const leader = topContenders[0]
  const isChanging = changingDivision === division

  return (
    <Card
      key={division}
      className={`rounded-2xl transition-[color,background-color,border-color,box-shadow] duration-300 overflow-hidden ${
        winner
          ? "border-2 border-amber-400/80 dark:border-amber-500/70 shadow-md shadow-amber-500/10 bg-linear-to-b from-amber-500/10 via-card to-card"
          : "border border-border/80 bg-card/60"
      }`}
    >
      {/* Division Card Header */}
      <DivisionDeclarationHeader division={division} winner={winner} />

      <CardContent className="p-4 space-y-4">
        {/* State 1: Winner Already Declared (Unless changing) */}
        {winner && !isChanging ? (
          <DeclaredChampionSummary
            classrooms={classrooms}
            division={division}
            setChangingDivision={setChangingDivision}
            setDeleteDialog={setDeleteDialog}
            winner={winner}
          />
        ) : (
          /* State 2: Winner Not Declared OR Currently Changing */
          <div className="space-y-4">
            {isChanging && (
              <div className="flex items-center justify-between pb-2 border-b border-border/50">
                <span className="text-xs font-bold text-amber-600 dark:text-amber-400">Changing Champion</span>
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => setChangingDivision(null)}
                  className="h-7 text-xs px-2 cursor-pointer"
                >
                  Cancel
                </Button>
              </div>
            )}

            {/* Live #1 Leader from Evaluations */}
            {leader ? (
              <AutomaticChampionDeclaration
                batchDeclaring={batchDeclaring}
                division={division}
                handleDeclareWinner={handleDeclareWinner}
                leader={leader}
                loading={loading}
              />
            ) : (
              <div className="p-3 text-center rounded-xl bg-muted/40 border border-border/60">
                <p className="text-xs font-semibold text-muted-foreground">
                  No evaluations found in {currentMonthLabel} {selectedYear}
                </p>
              </div>
            )}

            {/* Runner-Ups Quick Picker (if > 1 classroom in topContenders) */}
            {topContenders.length > 1 && (
              <DivisionStandingsPreview
                batchDeclaring={batchDeclaring}
                division={division}
                handleDeclareWinner={handleDeclareWinner}
                loading={loading}
                topContenders={topContenders}
              />
            )}

            {/* Manual Override Selector */}
            <ManualChampionDeclaration
              batchDeclaring={batchDeclaring}
              classrooms={classrooms}
              division={division}
              handleManualDeclare={handleManualDeclare}
              loading={loading}
              manualSelection={manualSelection}
              setManualSelection={setManualSelection}
            />
          </div>
        )}
      </CardContent>
    </Card>
  )
}

